pub fn cg_define_at() -> Ref<List<&'static Dpos>> {
    kayak_rt::kept_constant!(ONCE: Ref<List<&'static Dpos>>);
    once(&ONCE, || {
        kayak_rt::heap_new(nil::<&'static Dpos>())
    })
}

pub fn define_at(mut ds: List<&'static Dpos>, mut a: i64) -> i64 {
    loop {
        if null_p(ds) {
            return -1i64;
        } else if {
            let tagcase_ = car(ds);
            match *tagcase_ {
                Dpos::Dpos(l, d) => {
                    i64_eq(l, a)
                }
            }
        } {
            let tagcase_ = car(ds);
            match *tagcase_ {
                Dpos::Dpos(l, d) => {
                    return d;
                }
            }
        } else {
            ds = cdr(ds);
            continue;
        }
    }
}

pub fn c_adjoin(xs: Strings, n: Str) -> Strings {
    if string_member_p(n, xs) {
        xs
    } else {
        kayak_rt::heap_cons(n, xs)
    }
}

pub fn c_bound_names(mut bs: Cbinds, mut bound: Strings) -> Strings {
    loop {
        if null_p(bs) {
            return bound;
        } else {
            (bs, bound) = (cdr(bs), {
                let tagcase_ = car(bs);
                match *tagcase_ {
                    Cbind::Cbind(n, x) => {
                        kayak_rt::heap_cons(n, bound)
                    }
                }
            });
            continue;
        }
    }
}

pub fn c_bound_exps(bs: Cbinds) -> Cxs {
    map(lambda1s(move |b: &'static Cbind| {
        let tagcase_ = b;
        match *tagcase_ {
            Cbind::Cbind(n, x) => {
                x
            }
        }
    }), bs)
}

pub fn c_names(mut ns: Strings, mut bound: Strings) -> Strings {
    loop {
        if null_p(ns) {
            return bound;
        } else {
            (ns, bound) = (cdr(ns), kayak_rt::heap_cons(car(ns), bound));
            continue;
        }
    }
}

// The names free in `x`, not `bound`, onto `acc`, the newest first, in
// Fixpt's order: what an expression's parts are walked in.

// A standard name, whatever a program binds it to (Fixpt's `(with #%fx
// name)`, C221): what a quote builds with.
pub fn std_var(n: Str, a: i64) -> &'static Cx {
    x_var(string_append(str_lit("#%fx:"), n), a)
}

// Written so, `(with #%fx n)` is marked apart (`#%fx!:`), as Fixpt keeps
// its `with`, which its register code takes for no operation done in line
// (C248).
pub fn std_written_var(n: Str, a: i64) -> &'static Cx {
    x_var(string_append(str_lit("#%fx!:"), n), a)
}

pub fn std_written_p(n: Str) -> bool {
    has_prefix_p(n, str_lit("#%fx!:"))
}

pub fn std_marked_p(n: Str) -> bool {
    (has_prefix_p(n, str_lit("#%fx:")) || std_written_p(n))
}

pub fn std_named(n: Str) -> Str {
    if std_written_p(n) {
        after_prefix(n, str_lit("#%fx!:"))
    } else if std_marked_p(n) {
        after_prefix(n, str_lit("#%fx:"))
    } else {
        n
    }
}

pub fn c_free_all(mut es: Cxs, mut bound: Strings, mut acc: Strings) -> Strings {
    loop {
        if null_p(es) {
            return acc;
        } else {
            (es, acc) = (cdr(es), c_free(car(es), bound, acc));
            continue;
        }
    }
}

pub fn c_free(mut x: &'static Cx, mut bound: Strings, mut acc: Strings) -> Strings {
    loop {
        let tagcase_ = x;
        match *tagcase_ {
            Cx::XVar(n, a) => {
                if (std_marked_p(n) || string_member_p(n, bound)) {
                    return acc;
                } else {
                    return c_adjoin(acc, n);
                }
            }
            Cx::XLambda(ps, body, a) => {
                (x, bound) = (body, c_names(ps, bound));
                continue;
            }
            Cx::XApp(f, args, a) => {
                (x, acc) = (f, c_free_all(args, bound, acc));
                continue;
            }
            Cx::XIf(t, th, el, a) => {
                (x, acc) = (t, c_free(th, bound, c_free(el, bound, acc)));
                continue;
            }
            Cx::XLetrec(bs, body, a) => {
                let inner = c_bound_names(bs, bound);
                (x, bound, acc) = (body, inner, c_free_all(c_bound_exps(bs), inner, acc));
                continue;
            }
            Cx::XLet(bs, body, a) => {
                (x, bound, acc) = (body, c_bound_names(bs, bound), c_free_all(c_bound_exps(bs), bound, acc));
                continue;
            }
            Cx::XBegin(es, a) => {
                return c_free_all(es, bound, acc);
            }
            Cx::XProj(x, a) => {
                return c_free(x, bound, acc);
            }
            Cx::XProduct(fs, a) => {
                return c_free_all(c_bound_exps(fs), bound, acc);
            }
            Cx::XExtract(p, i, a) => {
                x = p;
                continue;
            }
            Cx::XSum(t, v, a) => {
                x = v;
                continue;
            }
            Cx::XTagcase(s, arms, els, k, a) => {
                (x, acc) = (s, c_free_arms(arms, bound, c_free_else(els, bound, acc)));
                continue;
            }
            Cx::XPrompt(t, body, h, a) => {
                (x, acc) = (t, c_free(body, bound, c_free(h, bound, acc)));
                continue;
            }
            Cx::XBloblet(op, i, xs, a) => {
                return c_free_all(xs, bound, acc);
            }
            Cx::XRegion(k, r, body, a) => {
                (x, bound) = (body, kayak_rt::heap_cons(r, bound));
                continue;
            }
            Cx::XRlambda(r, l, a) => {
                (x, acc) = (r, c_free(l, bound, acc));
                continue;
            }
            Cx::XModule(its, a) => {
                let inner = c_names(map(&cmem_name, its), bound);
                return c_free_all(map(&cmem_value, its), inner, acc);
            }
            Cx::XWith(m, ns, ks, body, a) => {
                (x, bound, acc) = (body, c_names(ns, bound), c_free(m, bound, acc));
                continue;
            }
            Cx::XReshape(y, ps, a) => {
                x = y;
                continue;
            }
            _ => {
                let y = tagcase_;
                return acc;
            }
        }
    }
}

pub fn c_free_arms(mut arms: List<&'static Carm>, mut bound: Strings, mut acc: Strings) -> Strings {
    loop {
        if null_p(arms) {
            return acc;
        } else {
            let tagcase_ = car(arms);
            match *tagcase_ {
                Carm::Carm(t, p, ns, body) => {
                    (arms, acc) = (cdr(arms), c_free(body, c_names(ns, bound), acc));
                    continue;
                }
            }
        }
    }
}

pub fn c_free_else(els: Cbinds, bound: Strings, acc: Strings) -> Strings {
    if null_p(els) {
        acc
    } else {
        let tagcase_ = car(els);
        match *tagcase_ {
            Cbind::Cbind(n, x) => {
                c_free(x, kayak_rt::heap_cons(n, bound), acc)
            }
        }
    }
}

pub fn c_mentions_p(x: &'static Cx, n: Str) -> bool {
    string_member_p(n, c_free(x, nil::<Str>(), nil::<Str>()))
}

pub fn c_free_names(x: &'static Cx) -> Strings {
    c_free(x, nil::<Str>(), nil::<Str>())
}

