// Where to halve `n` sorted entries: nearest the middle, between unequal
// values (0 if none).
pub fn case_mid(es: List<&'static Ckey>, n: i64) -> i64 {
    let up = case_mid_up(es, i64_quotient(n, 2i64), n);
    if i64_eq(up, n) {
        case_mid_down(es, i64_quotient(n, 2i64))
    } else {
        up
    }
}

