// A lambda's word's name, but for where its body starts: `named`'s, if it
// has one (a global's); else for the definition it is in, and the name it
// is bound to there (`own`, a `letrec`'s, or `bound`, a `let`'s), or
// `lambda`.
pub fn c_word_base(named: Strings, own: Strings, bound: Strings) -> Str {
    if null_p(named) {
        let (inner, scope) = (if not(null_p(own)) {
            car(own)
        } else if not(null_p(bound)) {
            car(bound)
        } else {
            str_lit("lambda")
        }, get(c_scope_name()));
        if null_p(scope) {
            inner
        } else {
            string_append(car(scope), string_append(str_lit("/"), inner))
        }
    } else {
        car(named)
    }
}

pub fn c_word_symbol(base: Str, named: Strings, body: &'static Cx) -> Str {
    if null_p(named) {
        string_append(base, string_append(str_lit("@"), i64_to_string(cx_start(body))))
    } else {
        car(named)
    }
}

// Whether `name` is an equality of the same word, as `eq` does it.
pub fn std_eq_name_p(n: Str) -> bool {
    (string_eq_p(n, str_lit("char=?")) || string_eq_p(n, str_lit("symbol=?")) || string_eq_p(n, str_lit("wglobal=?")) || string_eq_p(n, str_lit("eq?")) || string_eq_p(n, str_lit("bool=?")))
}

pub fn std_nil_name_p(n: Str) -> bool {
    (string_eq_p(n, str_lit("nil")) || string_eq_p(n, str_lit("no-pair")))
}

pub fn std_primitive(n: Str) -> Str {
    standard::standard_primitive(n)
}

// A standard operation's arity by its type, as the checker reads it
// (`primitives`, check-defs.kfx): the parameters of its `subr`, under a
// `poly` if it is one; -1 for none (C234: `bitwise-not` as a value, Fixpt's
// `stubs.fx`).
pub fn subr_params(mut t: &'static Sexp) -> i64 {
    loop {
        if head_is_p(t, str_lit("poly")) {
            t = car(cdr(cdr(items(t))));
            continue;
        } else if head_is_p(t, str_lit("subr")) {
            return size(items(car(cdr(cdr(items(t))))));
        } else {
            return -1i64;
        }
    }
}

pub fn std_arity_in(mut ps: Sexps, mut n: Str) -> i64 {
    loop {
        if null_p(ps) {
            return -1i64;
        } else if sym_is_p(car(items(car(ps))), n) {
            return subr_params(second(items(car(ps))));
        } else {
            ps = cdr(ps);
            continue;
        }
    }
}

// kayak-rt's primitives' table read, kept once read (C262): read again for
// each name `c-arity` was asked of, each variable's name new to the
// analyses, it was most of what the reader read in compiling a program.
